		// 3. TOMBOL NYALAKAN SUARA (UNMUTE)
		_this.btn_volon.on("click", function() {
			_this.btn_voloff.visible = true;
			_this.btn_volon.visible = false;
			
			// Kembalikan ke volume sebelumnya
			createjs.Sound.volume = volumeSekarang;
		});
		
		// -----------------------------------------------------------
		// 4. TOMBOL VOLUME UP (+0.1)
		_this.btn_volup.on("click", function() {
			volumeSekarang += 0.1;
			if (volumeSekarang > 1) volumeSekarang = 1;
			
			createjs.Sound.volume = volumeSekarang;
			console.log("Volume Naik: " + Math.round(volumeSekarang * 100) + "%");
		});
		
		// -----------------------------------------------------------
		// 5. TOMBOL VOLUME DOWN (-0.1)
		_this.btn_voldown.on("click", function() {
			volumeSekarang -= 0.1;
			if (volumeSekarang < 0) volumeSekarang = 0;
			
			createjs.Sound.volume = volumeSekarang;
			console.log("Volume Turun: " + Math.round(volumeSekarang * 100) + "%");
		});
		
		// -----------------------------------------------------------
		// 6. TOMBOL OKE (GOTO FRAME 1)
		_this.btn_oke.on("click", function() {
			// Frame 1 di HTML5 adalah index 0
			_this.gotoAndStop(0); 
		});
