	this.frame_11 = function() {
		this.stop();
		var root = this; 
		
		// --- 1. AMBIL DATA AKHIR ---
		var totalSoal = window.soalAcak ? window.soalAcak.length : 0;
		var jumlahBenar = window.skorBenar || 0;
		var jumlahSalah = totalSoal - jumlahBenar;
		
		// Rumus Nilai (0-100)
		var skorAkhir = totalSoal > 0 ? Math.round((jumlahBenar / totalSoal) * 100) : 0;
		
		// --- 2. TAMPILKAN KE TEXT FIELD ---
		if (this.txt_benar) this.txt_benar.text = String(jumlahBenar);
		if (this.txt_salah) this.txt_salah.text = String(jumlahSalah);
		if (this.txt_nilai) this.txt_nilai.text = String(skorAkhir);
		
		// --- 3. LOGIKA EMOTICON & TEKS PESAN ---
		if (this.mc_emosi) {
		    this.mc_emosi.stop(); // Pastikan tidak jalan sendiri (looping)
		    
		    if (skorAkhir >= 70) {
		        // --- JIKA LULUS (70 ke atas) ---
		        this.mc_emosi.gotoAndStop(0); // Menampilkan Frame 1 (Bahagia)
		        
		        if (this.txt_pesan) {
		            this.txt_pesan.text = "Selamat, Anda Lulus!";
		            // Opsional: Ganti warna teks jadi Hijau (Hex Code)
		            this.txt_pesan.color = "#231F20"; 
		        }
		    } else {
		        // --- JIKA GAGAL (di bawah 70) ---
		        this.mc_emosi.gotoAndStop(1); // Menampilkan Frame 2 (Menangis)
		        
		        if (this.txt_pesan) {
		            this.txt_pesan.text = "Anda Tidak lulus Silahkan Ulang Kembali";
		            // Opsional: Ganti warna teks jadi Merah (Hex Code)
		            this.txt_pesan.color = "#231F20"; 
		        }
		    }
		}
		
		// --- 4. TOMBOL RESTART (btn_ulang) ---
		if (this.btn_ulang) {
		    this.btn_ulang.cursor = "pointer";
		    this.btn_ulang.on("click", function() {
		        // Reset data global
		        window.indeks = 0;
		        window.skorBenar = 0;
		        window.jawabanUser = "";
		        
		        // Kembali ke frame berlabel "awal"
		        root.gotoAndStop("awal"); 
		    });
		}
		this.btn_setting.visible;
	}

