if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	// timeline functions:
	this.frame_34 = function() {
		this.stop();
		var _this = this;
		
		// --- 1. LOGIKA SUARA PROFILE (HANYA UNTUK VO PROFILE) ---
		// Menggunakan playVO agar backsound tetap menyala di latar belakang
		if (typeof playVO === "function") {
		    playVO("profileID"); 
		} else {
		    // Jika fungsi playVO belum terbaca, kita hentikan VO sebelumnya saja
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    exportRoot.currentVO = createjs.Sound.play("profileID", {volume: 0.6});
		}
		
		// --- 2. LOGIKA TOMBOL NEXT ---
		_this.btn_next80.cursor = "pointer";
		_this.btn_next80.removeAllEventListeners("click");
		
		_this.btn_next80.on('click', function() {
		    // HANYA matikan suara narasi saat pindah slide
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    
		    if (_this.currentFrame < _this.totalFrames - 1) {
		        var nextFrame = _this.currentFrame + 1;
		        _this.gotoAndStop(nextFrame);
		        console.log("Pindah ke slide profile berikutnya");
		    } else {
		        console.log("Sudah di slide terakhir.");
		    }
		});
		
		// --- 3. LOGIKA TOMBOL BACK SLIDE ---
		_this.btn_back70.cursor = "pointer";
		_this.btn_back70.removeAllEventListeners("click");
		
		_this.btn_back70.on('click', function() {
		    // HANYA matikan suara narasi saat mundur slide
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    
		    if (_this.currentFrame > 0) {
		        var prevFrame = _this.currentFrame - 1;
		        _this.gotoAndStop(prevFrame);
		        console.log("Mundur ke slide profile sebelumnya");
		    } else {
		        console.log("Ini sudah slide pertama.");
		    }
		});
		
		// --- 4. LOGIKA TOMBOL KEMBALI KE MENU UTAMA ---
		this.btn_back_profile.cursor = "pointer";
		this.btn_back_profile.on("click", function() {
		    // HANYA matikan suara narasi profile, backsound tetap aman
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    
		    exportRoot.gotoAndStop("menu_utama");
		}.bind(this));
	}
