	cjs.MovieClip.apply(this,[props]);

	// timeline functions:
	this.frame_39 = function() {
		this.stop();
		var _this = this;
		
		// --- 1. LOGIKA SUARA (HANYA UNTUK VO LOGIN) ---
		// Kita gunakan fungsi playVO agar musik backsound tidak mati
		if (typeof playVO === "function") {
		    playVO("loginID"); 
		} else {
		    // Jika fungsi playVO belum ada di frame 1, pakai cara ini agar backsound aman
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    exportRoot.currentVO = createjs.Sound.play("loginID", {volume: 0.6});
		}
		
		// --- 2. FUNGSI MEMBUAT INPUT HTML (KODE ASLI KAMU) ---
		function getOrCreateInput(id, x, y, w, h) {
		    var existingInput = document.getElementById(id);
		    if (existingInput) return existingInput;
		
		    var input = document.createElement("input");
		    input.id = id;
		    input.type = "text";
		    input.style.position = "absolute";
		    
		    var canvas = document.getElementById("canvas");
		    var rect = canvas.getBoundingClientRect();
		    
		    input.style.left = (rect.left + window.pageXOffset + x) + "px";
		    input.style.top = (rect.top + window.pageYOffset + y) + "px";
		    input.style.width = w + "px";
		    input.style.height = h + "px";
		    
		    input.style.zIndex = "10000";
		    input.style.background = "transparent"; 
		    input.style.border = "none";             
		    input.style.outline = "none";            
		    input.style.pointerEvents = "auto";
		    input.style.boxSizing = "border-box"; 
		    input.style.textAlign = "center";
		    input.style.lineHeight = (h - 5) + "px"; 
		    input.style.paddingBottom = "8px"; 
		    
		    input.style.fontFamily = "Verdana, sans-serif";
		    input.style.fontWeight = "bold";
		    input.style.fontSize = "24px";
		    input.style.color = "#000000"; 
		    
		    document.body.appendChild(input);
		    return input;
		}
		
		var inputNama = getOrCreateInput("input_nama", 402, 137, 312, 45);
		var inputKelas = getOrCreateInput("input_kelas", 401, 231, 313, 45);
		
		// --- 3. SETUP TEKS DYNAMIC WARNING ---
		if(_this.txt_warning) {
		    _this.txt_warning.text = ""; 
		    _this.txt_warning.color = "#000000"; 
		    _this.txt_warning.font = "bold 19px 'Verdana'"; 
		    _this.txt_warning.textAlign = "center"; 
		    _this.txt_warning.x = 558; 
		}
		
		// --- 4. LOGIKA TOMBOL LOGIN (DIPERBAIKI AGAR BACKSOUND TIDAK MATI) ---
		this.btn_login.cursor = "pointer";
		this.btn_login.removeAllEventListeners(); 
		
		this.btn_login.on("click", function() {
		    var valNama = inputNama.value.trim();
		    var valKelas = inputKelas.value.trim();
		
		    if (valNama === "" || valKelas === "") {
		        if(_this.txt_warning) {
		            _this.txt_warning.text = "Nama dan Kelas tidak boleh kosong!";
		            _this.txt_warning.alpha = 0;
		            createjs.Tween.get(_this.txt_warning, {override:true}).to({alpha: 1}, 300);
		            
		            setTimeout(function(){ 
		                _this.txt_warning.text = ""; 
		            }, 3000);
		        }
		    } else {
		        window.namaUser = valNama;
		        window.kelasUser = valKelas;
		
		        // --- HANYA STOP SUARA VO LOGIN, BUKAN BACKSOUND ---
		        if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		
		        if (inputNama && inputNama.parentNode) inputNama.parentNode.removeChild(inputNama);
		        if (inputKelas && inputKelas.parentNode) inputKelas.parentNode.removeChild(inputKelas);
		
		        exportRoot.gotoAndStop(4); 
		    }
		});
	}

