if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {login:3,menu_utama:4,petunjuk:5,materi:6,praktikum:7,pilih_praktikum:9,evaluasi:13,profil:14,isi_praktikum1:10,isi_praktikum2:11,isi_praktikum3:12,karakter:8};
