	this.actionFrames = [0,1,2,9];
	// timeline functions:
	this.frame_0 = function() {
		if (!exportRoot.alreadyRegistered) {
		    // 1. DAFTAR SEMUA SUARA
		    createjs.Sound.registerSound("sounds/backsoundwav.mp3", "backsoundID");
		    createjs.Sound.registerSound("sounds/HalamanUtama1wav.mp3", "halamanUtamaID");
		    createjs.Sound.registerSound("sounds/Halamanlogin1wav.mp3", "loginID");
		    createjs.Sound.registerSound("sounds/Materiwav.mp3", "materiID");
		    createjs.Sound.registerSound("sounds/Petunjukwav.mp3", "petunjukID");
		    createjs.Sound.registerSound("sounds/HalamanPetunjuk.wav", "HalamanPetunjukID");
		    createjs.Sound.registerSound("sounds/Profilewav.mp3", "profileID");
		
		    exportRoot.alreadyRegistered = true;
		}
		
		// 2. FUNGSI KHUSUS VO (Hanya untuk narasi)
		window.playVO = function(id) {
		    if (exportRoot.currentVO) {
		        exportRoot.currentVO.stop(); 
		    }
		    exportRoot.currentVO = createjs.Sound.play(id, {volume: 0.7});
		}
		
		// 3. FUNGSI KHUSUS BACKSOUND (Looping selamanya)
		window.playBacksound = function(id) {
		    if (!exportRoot.bgmInstance) {
		        // Volume 0.4 agar musiknya terdengar tapi tidak menutupi narasi
		        exportRoot.bgmInstance = createjs.Sound.play(id, {loop: -1, volume: 0.4});
		    }
		}
		
		// 4. PANCINGAN KLIK (FOKUS KE BACKSOUND)
		stage.on("stagemousedown", function() {
		    // Jalankan backsound saja dulu saat klik pertama
		    playBacksound("backsoundID"); 
		    console.log("Backsound Berhasil Dimulai!");
		}, this, true);
		
		// 2. LOGIKA TIMELINE ANDA
		this.stop();
		
		// Pindah otomatis setelah 2 detik (2000 milidetik)
		setTimeout(function() {
		    this.gotoAndStop(1); // Pindah ke Frame 2 (Indeks 1)
		}.bind(this), 2000);
		playSound("backsoundwav");
	}
